import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.4s5LDCII.js";const b=JSON.parse('{"title":"成人肥胖食养指南（2024年版）","description":"国家卫健委《成人肥胖食养指南（2024年版）》要点导读：全谷物主食、足量蔬果、控制能量，附分地区分季节食谱示例。","frontmatter":{"title":"成人肥胖食养指南（2024年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2024年版","published":"2024-02","document_no":"国卫办食品函〔2024〕53号","source_url":"https://www.nhc.gov.cn/wjw/c100378/202402/afd5dda4bd6745fda10aad8d43a16369/files/1732845128308_77058.pdf","status":"现行","tags":["肥胖","减重","食养","饮食指导"],"reviewed":false,"description":"国家卫健委《成人肥胖食养指南（2024年版）》要点导读：全谷物主食、足量蔬果、控制能量，附分地区分季节食谱示例。"},"headers":[],"relativePath":"guides/obesity-2024.md","filePath":"guides/obesity-2024.md"}'),d={name:"guides/obesity-2024.md"};function s(i,t,l,n,c,h){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="成人肥胖食养指南-2024年版" tabindex="-1">成人肥胖食养指南（2024年版） <a class="header-anchor" href="#成人肥胖食养指南-2024年版" aria-label="Permalink to &quot;成人肥胖食养指南（2024年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本导读由 AI 起草，尚未逐条对照原文校验；一切以原文为准。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/wjw/c100378/202402/afd5dda4bd6745fda10aad8d43a16369/files/1732845128308_77058.pdf" target="_blank" rel="noreferrer">指南全文 PDF</a>）· 一级来源</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>成人超重与肥胖人群，以及希望预防肥胖、管理体重的一般人群。</p><h2 id="关键要点-摘要" tabindex="-1">关键要点（摘要） <a class="header-anchor" href="#关键要点-摘要" aria-label="Permalink to &quot;关键要点（摘要）&quot;">​</a></h2><ul><li><strong>主食以全谷物为主</strong>：鼓励全谷物至少占谷物的一半，适当增加粗粮，减少精白米面。</li><li><strong>蔬果足量、选对品种</strong>：保障新鲜蔬果且品种多样，同时减少高糖水果和高淀粉蔬菜的摄入。</li><li><strong>控制总能量、吃动平衡</strong>：在膳食控制的同时配合规律运动，强调长期坚持而非极端节食。</li><li><strong>辨证施膳</strong>：指南结合中医食养理念给出建议（详见原文）。</li></ul><h2 id="怎么用这份文件" tabindex="-1">怎么用这份文件 <a class="header-anchor" href="#怎么用这份文件" aria-label="Permalink to &quot;怎么用这份文件&quot;">​</a></h2><p>指南按<strong>不同地区、不同季节</strong>给出食谱套餐示例，可就近、就季节参考；具体能量目标建议在医生或营养师指导下个体化确定，具体以原文为准。</p><h2 id="溯源信息" tabindex="-1">溯源信息 <a class="header-anchor" href="#溯源信息" aria-label="Permalink to &quot;溯源信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2024 年版（现行）</td></tr><tr><td>印发时间</td><td>2024 年 2 月（具体日期待核对原文）</td></tr><tr><td>发文字号</td><td>国卫办食品函〔2024〕53号（待人工复核）</td></tr></tbody></table>',11)])])}const p=a(d,[["render",s]]);export{b as __pageData,p as default};
